public bool IsIsomorphicTwoMaps(string s, string t)
{
    if (s.Length != t.Length) return false;
    var s2t = new Dictionary<char, char>();
    var t2s = new Dictionary<char, char>();
    for (int i = 0; i < s.Length; i++)
    {
        char a = s[i], b = t[i];
        if (s2t.ContainsKey(a) && s2t[a] != b) return false;
        if (t2s.ContainsKey(b) && t2s[b] != a) return false;
        s2t[a] = b;
        t2s[b] = a;
    }
    return true;
}

public bool IsIsomorphic(string s, string t)
{
    if (s.Length != t.Length) return false;
    var map = new Dictionary<char, char>();
    var used = new HashSet<char>();
    for (int i = 0; i < s.Length; i++)
    {
        char a = s[i], b = t[i];
        if (map.ContainsKey(a))
        {
            if (map[a] != b) return false;
        }
        else
        {
            if (!used.Add(b)) return false;
            map[a] = b;
        }
    }
    return true;
}
